from research_helpers import *
S=ev('https://aspisotopes.com/semiconductors/','Current issuer describes enrichedSi28 and depletedGe73 semiconductor materials. Generic website commercial claims checked against dated operational updates.')
M=ev('https://aspisotopes.com/medical/','Issuer identifies isotope precursor development opportunities Mo100,Yb176,Zn68,C14,Ni64. DownstreamTc99m/Ga68/Cu64/Cu67/Lu177 drugs not inferred as proprietary ASPI products.')
Q=ev('https://ir.aspisotopes.com/sec-filings/all-sec-filings/content/0001193125-26-352603/aspi-20260630.htm','June30 2026 issuer reports no enriched isotope sales revenue and future shipment targets. Additional isotope targets explicitly described as future possibilities.')
U=ev('https://ir.aspisotopes.com/news-events/press-releases/detail/119/asp-isotopes-hosts-inaugural-capital-markets-day-and','September8 2026 issuer still expects first commercial stable-isotope shipments over next12months. Commercial deliveries not assumed from elapsed target dates. Renergen subsidiary relationship confirmed.')
T=ev('https://aspisotopes.com/technology/','Two named enrichment technologies and isotope target sets. Nuclear fuel generation programmes excluded from storage scope.')
ps=[p('ASPI enriched Silicon-28','Isotopically enriched silicon semiconductor feedstock.',S,'development',typ='product',sector='semiconductors',sub='materials_and_packaging',evidence=[S,Q,U]),p('ASPI depleted Germanium-73','Germanium depleted in spin-bearingGe73 for semiconductor/quantum applications.',S,'research',typ='development_program',sector='semiconductors',sub='materials_and_packaging',evidence=[S,Q])]
for isotope,life,sub,desc in [('Carbon-14','development','research_tools','Radiolabelling feedstock for pharmacokinetic studies.'),('Ytterbium-176','development','research_tools','Stable precursor for production of therapeuticLu177.'),('Molybdenum-100','research','research_tools','Stable precursor programme for diagnosticTc99m production.'),('Zinc-68','research','research_tools','Stable precursor programme for medical radioisotopes.'),('Nickel-64','research','research_tools','Stable precursor programme forCu64 production.'),('Xenon-129','research','diagnostics','Future medical isotope enrichment target.'),('Xenon-136','research','research_tools','Future medical isotope enrichment target.'),('Gadolinium-160','research','research_tools','Future isotope enrichment target disclosed in issuer filing.')]:ps.append(p('ASPI enriched '+isotope,desc,M,life,typ='product'if life=='development'else'development_program',sub=sub,evidence=[M,Q,U]if life=='development'else[M,Q]))
for name,desc in [('Aerodynamic Separation Process','Gas-phase isotope separation technology for medical and semiconductor materials.'),('Quantum Enrichment','Laser isotope separation technology for medical precursor materials.')]:ps.append(p('ASPI '+name,desc,T,'development',typ='technology',sub='research_tools'))
cs=[company('ASP Isotopes Inc. Common Stock',ps,[S,M,Q,U,T],'Reviewed official semiconductor/medical/technology pages,June2026 filing andSeptember2026 update. Twelve feedstock/technology/target records captured; future isotope opportunities remain research, first delivery not assumed. Nuclear fuels/LNG outside four-sector scope. PETLabs radiopharmacy product identities, US subsidiaries, helium electronic grade, individual isotope form/purity and any subsequent shipment confirmations remain.')]
(out/'batch-0069.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
